# Sufficient Statistics
# ====================================================================
class SuffStats:
    def __init__(self, T, Y, A, K):
        self.K = K
        self.has_T = T is not None
        N = len(Y)
        DA = np.zeros((N, K))
        for k in range(K):
            DA[:, k] = (A == k).astype(float)
        self.p_A = DA.mean(0)
        self.E_Y = Y.mean()
        self.E_YD = (DA * Y[:, None]).mean(0)
        if self.has_T:
            self.E_T = T.mean()
            self.E_T2 = (T ** 2).mean()
            self.E_TY = (T * Y).mean()
            self.E_TD = (DA * T[:, None]).mean(0)


class IVSuffStats:
    def __init__(self, Z, Y, A, K):
        self.K = K
        z1 = Z == 1
        z0 = Z == 0
        self.RF = Y[z1].mean() - Y[z0].mean()
        self.FS = np.zeros(K)
        for k in range(K):
            self.FS[k] = (A[z1] == k).mean() - (A[z0] == k).mean()


# ====================================================================
# Plim computation (single C)
# ====================================================================
def plim_ols_with_T(C, ss):
    K = ss.K
    q = C @ ss.p_A
    ct = C @ ss.E_TD
    cy = C @ ss.E_YD
    dim = K + 1
    EZZ = np.zeros((dim, dim))
    EZZ[0, 0] = 1.0
    EZZ[0, 1] = ss.E_T
    EZZ[1, 0] = ss.E_T
    EZZ[1, 1] = ss.E_T2
    EZZ[0, 2:] = q[1:]
    EZZ[2:, 0] = q[1:]
    EZZ[1, 2:] = ct[1:]
    EZZ[2:, 1] = ct[1:]
    for j in range(K - 1):
        EZZ[j + 2, j + 2] = q[j + 1]
    EZY = np.zeros(dim)
    EZY[0] = ss.E_Y
    EZY[1] = ss.E_TY
    EZY[2:] = cy[1:]
    try:
        return np.linalg.solve(EZZ, EZY)
    except np.linalg.LinAlgError:
        return np.full(dim, np.nan)


def plim_ols_exposure(C, ss):
    K = ss.K
    q = C @ ss.p_A
    cy = C @ ss.E_YD
    dim = K
    EZZ = np.zeros((dim, dim))
